@startuml
class GasStation {
  +id : string
  +address : string
}

class FuelPump {
  +number : int
  +isSelfService : boolean
}

class Fuel {
  +name : string
  +octaneRating : int
}

class DailyPrice {
  +date : date
  +pricePerLiter : float
}

class FuelPurchase {
  +id : string
  +litersDispensed : float
}

GasStation "1" *-- "1..12" FuelPump
GasStation "1" -- "*" DailyPrice
FuelPump "1" -- "*" Fuel : offers
FuelPump "1" -- "*" FuelPurchase : is used at
Fuel "1" -- "*" DailyPrice : applies to
DailyPrice "1" -- "1" FuelPurchase : is used for
@enduml

